'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import { translate, type Locale } from '@/i18n/messages';
import {
 Activity, ArrowRight, ArrowUpRight, Bell, CalendarClock, Check, CheckCheck, ChevronDown,
 ChevronRight, CircleDollarSign, CircleStop, Clock3, Command, ExternalLink, FileSearch, Filter,
 Flame, Globe2, Heart, Inbox, Kanban, LayoutDashboard, Mail, MessageCircle, MoreHorizontal,
 Plus, Search, Send, Settings2, ShieldCheck, Sparkles, Target, TrendingUp, Upload, UsersRound,
 Wallet, X, Zap,
} from 'lucide-react';

type EntityId=string|number;
type Tab='HOJE'|'IMPORTAR'|'LEADS'|'FILA'|'CHAT'|'QUENTES'|'FUNIL'|'CONFIGURAÇÃO FINAL';
type Evidence={id:EntityId;kind:string;observation:string;sourceUrl?:string|null;observedAt?:string;confidence:number};
type Lead={id:EntityId;name:string;email:string|null;website:string|null;city:string;niche:string;status:string;siteStatus:string;reply:string|null;summary:string|null;subject:string|null;body:string|null;hot:number;value:number;source:string;createdAt:string;score:number;scoreReasons:string[];demoBrief?:string|null;threadId?:string|null;evidence:Evidence[];synthetic?:boolean};
type ActivityItem={id:EntityId;kind:string;message:string;createdAt:string;leadId?:EntityId|null};
type Task={id:EntityId;leadId?:EntityId|null;kind:string;title:string;dueAt?:string|null;status:string;details?:string|null};
type AppData={leads:Lead[];settings:Record<string,string>;accounts:any[];activities:ActivityItem[];tasks:Task[];campaigns:any[];messages:any[];suppressed:any[];queueCount:number;sentToday:number;demo:boolean;aiDemo:boolean;gmailDemo:boolean;fx?:{currency:string;rateDate:string;rate:number}|null;stopped:boolean};
type ChatMessage={role:'assistant'|'user';text:string;proposal?:{type:string;ids:EntityId[];count:number};results?:{id:EntityId;name?:string;score?:number;synthetic?:boolean}[]};
type DraftState={lead:Lead;subject:string;body:string;reply:boolean};

const menu:{name:Tab;label:string;icon:any;phase:string}[]=[
 {name:'HOJE',label:'Dashboard',icon:LayoutDashboard,phase:'WORKSPACE'},
 {name:'LEADS',label:'Leads',icon:UsersRound,phase:'PROSPECTS'},
 {name:'FILA',label:'Campaigns',icon:Mail,phase:'OUTREACH'},
 {name:'CHAT',label:'AI Chat',icon:MessageCircle,phase:'ASSISTANT'},
 {name:'QUENTES',label:'Inbox',icon:Inbox,phase:'CONVERSATIONS'},
 {name:'FUNIL',label:'Sales',icon:Kanban,phase:'REVENUE'},
 {name:'IMPORTAR',label:'Import',icon:Upload,phase:'LEAD INTAKE'},
 {name:'CONFIGURAÇÃO FINAL',label:'Settings',icon:Settings2,phase:'SETUP'},
];
const stages=['Novo','Contactado','Respondeu','Quente','Demo enviada','Proposta','Fechado','Perdido'];
const statusLabel=(value:string)=>({'Novo':'New','Contactado':'Contacted','Respondeu':'Replied','Quente':'Interested','Demo enviada':'Demo sent','Proposta':'Proposal','Fechado':'Won','Perdido':'Lost','Não contactar':'Suppressed','A aprovar':'Needs review','CSV':'New','Tem site':'Website available','Sem site':'No website listed','Por verificar':'Not researched','Site em baixo':'Website unavailable','Só rede social':'Social profile only'}[value]||value);
const sourceLabel=(value:string)=>value==='Exemplo'?'Imported lead':value;

async function post(action:string,extra:Record<string,unknown>={}) {
 if(typeof navigator!=='undefined'&&!navigator.onLine)throw new Error('You’re offline. Sending and workspace changes need a connection.');
 const response=await fetch('/api/data',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,...extra})});
 const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not complete the action.');return result;
}
const money=(value:number,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:0}).format(value||0);
const dateTime=(value?:string|null)=>value?new Intl.DateTimeFormat('en-US',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(new Date(value)):'';

export default function Home(){
 const [tab,setTab]=useState<Tab>('HOJE');
 const [data,setData]=useState<AppData>({leads:[],settings:{},accounts:[],activities:[],tasks:[],campaigns:[],messages:[],suppressed:[],queueCount:0,sentToday:0,demo:true,aiDemo:true,gmailDemo:true,stopped:false});
 const [loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[toast,setToast]=useState('');
 const [online,setOnline]=useState(true);
 const [moreOpen,setMoreOpen]=useState(false);
 const [locale,setLocale]=useState<Locale>('pt-PT');
 const [query,setQuery]=useState(''),[city,setCity]=useState('All cities'),[niche,setNiche]=useState('All niches'),[selectedIds,setSelectedIds]=useState<EntityId[]>([]);
 const [csv,setCsv]=useState(''),[csvName,setCsvName]=useState(''),[csvNiche,setCsvNiche]=useState('');
 const [csvMap,setCsvMap]=useState<Record<string,string>>({});
 const [selected,setSelected]=useState<Lead|null>(null),[draft,setDraft]=useState<DraftState|null>(null),[campaignOpen,setCampaignOpen]=useState(false),[campaignMode,setCampaignMode]=useState<'review'|'auto'>('review'),[preview,setPreview]=useState<any>(null),[campaignAccountId,setCampaignAccountId]=useState('');
 const [goalOpen,setGoalOpen]=useState(false),[goalDraft,setGoalDraft]=useState('5000'),[goalCurrencyDraft,setGoalCurrencyDraft]=useState('USD');
 const [chatOpen,setChatOpen]=useState(false),[chatInput,setChatInput]=useState(''),[chatBusy,setChatBusy]=useState(false),[chatMessages,setChatMessages]=useState<ChatMessage[]>([{role:'assistant',text:'I can search your prospects, summarize replies, queue research, and prepare campaigns for your review.'}]);
 const [paletteOpen,setPaletteOpen]=useState(false),[paletteQuery,setPaletteQuery]=useState(''),[selfEmail,setSelfEmail]=useState(''),[selfAccountId,setSelfAccountId]=useState(''),[models,setModels]=useState({groq:'',diagnosis:'',chat:'',reviewer:'',nvidia:'',huggingface:''});

 const refresh=useCallback(async()=>{
  try {const response=await fetch('/api/data',{cache:'no-store'});if(response.status===401){window.location.assign('/login');return;}if(!response.ok)throw new Error('Could not refresh the workspace.');const next=await response.json();setData(next);try{localStorage.setItem('devrefract-last-workspace',JSON.stringify(next));}catch{}setLoading(false);}
  catch(error){try{const cached=localStorage.getItem('devrefract-last-workspace');if(cached){setData(JSON.parse(cached));setLoading(false);setToast('Offline · showing the last saved workspace. Sending and changes are paused.');return;}}catch{}setLoading(false);setToast(error instanceof Error?error.message:'Could not load the workspace.');}
 },[]);
 useEffect(()=>{void refresh();const timer=setInterval(()=>void refresh(),8000);return()=>clearInterval(timer);},[refresh]);
 useEffect(()=>{const update=()=>setOnline(navigator.onLine);update();window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update);};},[]);
 useEffect(()=>{const saved=localStorage.getItem('devrefract-locale');if(saved==='en-US'||saved==='pt-PT'){setLocale(saved);document.documentElement.lang=saved;}},[]);
 function changeLocale(value:Locale){setLocale(value);localStorage.setItem('devrefract-locale',value);document.documentElement.lang=value;}
 useEffect(()=>{setModels(current=>({groq:current.groq||data.settings.modelWriting||data.settings.groqModel||'',diagnosis:current.diagnosis||data.settings.modelDiagnosis||'',chat:current.chat||data.settings.modelChat||'',reviewer:current.reviewer||data.settings.modelReviewer||'',nvidia:current.nvidia||data.settings.modelNvidia||data.settings.nvidiaModel||'',huggingface:current.huggingface||data.settings.modelHuggingface||''}));if(!selfEmail&&data.settings.ownerEmail)setSelfEmail(data.settings.ownerEmail);},[data.settings.modelWriting,data.settings.modelDiagnosis,data.settings.modelChat,data.settings.modelReviewer,data.settings.modelNvidia,data.settings.modelHuggingface,data.settings.groqModel,data.settings.nvidiaModel,data.settings.ownerEmail]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4600);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{const listener=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();setPaletteOpen(true);setPaletteQuery('');}if(event.key==='Escape'){setPaletteOpen(false);setCampaignOpen(false);setSelected(null);setDraft(null);setGoalOpen(false);}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener);},[]);

 const leads=data.leads||[];
 const warm=leads.filter(l=>l.hot||l.status==='Quente');
 const inboxMessages=data.messages.filter((message:any)=>message.direction==='inbound').sort((a:any,b:any)=>new Date(b.receivedAt||0).getTime()-new Date(a.receivedAt||0).getTime());
 const queue=leads.filter(l=>l.status==='A aprovar');
 const contacted=leads.filter(l=>['Contactado','Respondeu','Quente','Demo enviada','Proposta','Fechado'].includes(l.status)).length;
 const closedEur=leads.filter(l=>l.status==='Fechado').reduce((sum,l)=>sum+(Number(l.value)||0),0);
 const goal=Number(data.settings.goal||5000),goalCurrency=data.settings.goalCurrency||'USD';
 const rate=Number(data.fx?.currency==='USD'?data.fx.rate:data.settings.fxUsdPerEur)||0;
 const closedTarget=goalCurrency==='USD'?closedEur*rate:closedEur;
 const progress=goal?Math.min(100,closedTarget/goal*100):0;
 const deadline=data.settings.goalDeadline||'2026-12-06';
 const daysLeft=Math.max(0,Math.ceil((new Date(`${deadline}T23:59:59`).getTime()-Date.now())/86400000));
 const filtered=useMemo(()=>leads.filter(l=>`${l.name} ${l.email||''} ${l.city} ${l.niche} ${l.status}`.toLowerCase().includes(query.toLowerCase())&&(city==='All cities'||l.city===city)&&(niche==='All niches'||l.niche===niche)),[leads,query,city,niche]);
 const shown=tab==='FILA'?filtered.filter(l=>l.status==='A aprovar'):tab==='QUENTES'?filtered.filter(l=>l.hot||l.status==='Quente'):filtered;
 const cities=useMemo(()=>['All cities',...new Set(leads.map(l=>l.city).filter(Boolean))],[leads]);
 const niches=useMemo(()=>['All niches',...new Set(leads.map(l=>l.niche).filter(Boolean))],[leads]);
 const accountLabel=data.accounts.length?`${data.accounts.length} Gmail account connected${data.accounts.length===1?'':'s'}`:'No Gmail account connected';

 async function act(action:string,extra:Record<string,unknown>={},success?:string){
  try{setBusy(true);const result=await post(action,extra);await refresh();setToast(success||(result.simulated?'Saved to sample data.':result.queued?`${result.queued} approved message(s) added to the queue.`:result.count!==undefined?`${result.count} drafts prepared.`:result.added!==undefined?`${result.added} prospects imported · ${result.dupes} duplicates skipped.`:'Changes saved.'));return result;}
  catch(error){setToast(error instanceof Error?error.message:'Something went wrong.');return null;}
  finally{setBusy(false);}
 }
 function changeSetting(key:string,value:string){setData(old=>({...old,settings:{...old.settings,[key]:value}}));}
 async function saveSettings(){const saved=await act('settings',{values:{...data.settings,modelWriting:models.groq,modelDiagnosis:models.diagnosis,modelChat:models.chat,modelReviewer:models.reviewer,modelNvidia:models.nvidia,modelHuggingface:models.huggingface}});if(saved){for(const key of ['googleClientId','googleClientSecret','groqKey','nvidiaKey','huggingfaceKey'])changeSetting(key,'');setToast('Settings saved securely.');}}
 function openCampaign(){
  const ids=selectedIds.length?selectedIds:filtered.filter(l=>l.email&&!['Fechado','Perdido','Não contactar'].includes(l.status)).map(l=>l.id);
  if(!ids.length){setToast('Select at least one prospect with an email.');return;}
  setCampaignMode(data.settings.auto==='1'?'auto':'review');
  setBusy(true);void post('campaign-preview',{ids}).then(result=>{setPreview(result);setCampaignOpen(true);}).catch(error=>setToast(error.message)).finally(()=>setBusy(false));
 }
 async function launchCampaign(){
  if(!preview?.eligible?.length)return;
  const result=await act('campaign-launch',{ids:preview.eligible.map((lead:any)=>lead.id),mode:campaignMode,confirmed:campaignMode==='auto',accountId:campaignAccountId||undefined},campaignMode==='auto'?'Campaign confirmed. The worker will send within the selected account’s limits.':'Campaign created; drafts are waiting for your review.');
  if(result){setCampaignOpen(false);setPreview(null);setSelectedIds([]);setTab('FILA');}
 }
 async function importCsv(){if(!csv.trim()){setToast('Choose a CSV file first.');return;}const result=await act('import',{csv,niche:csvNiche||'General',language:'en-US',mapping:csvMap});if(result){setToast(`${result.added} U.S. prospects imported · ${result.dupes} duplicates · ${result.outOfMarket||0} outside the U.S. skipped.`);if(result.added){setCsv('');setCsvName('');setCsvMap({});setTab('LEADS');}}}
 async function selectFile(file?:File){if(!file)return;setCsvName(file.name);setCsv(await file.text());setCsvMap({});}
 async function sendChat(){
  const text=chatInput.trim();if(!text||chatBusy)return;setChatInput('');setChatMessages(old=>[...old,{role:'user',text}]);setChatBusy(true);
  try{const result=await post('chat',{message:text});setChatMessages(old=>[...old,{role:'assistant',text:result.reply,proposal:result.proposal,results:result.results}]);}
  catch(error){setChatMessages(old=>[...old,{role:'assistant',text:error instanceof Error?error.message:'Could not check the workspace.'}]);}
  finally{setChatBusy(false);}
 }
 async function executeChatProposal(proposal:NonNullable<ChatMessage['proposal']>){
  if(proposal.type==='research'){
   const result=await act('research-selected',{ids:proposal.ids},`${proposal.count} research jobs queued.`);
   if(result)setChatMessages(old=>[...old,{role:'assistant',text:`Queued research for ${result.queued} real prospects. Synthetic example records remain local.`}]);
   return;
  }
  setSelectedIds(proposal.ids);setTab('LEADS');setChatOpen(false);setToast('Review the selected audience before launching the campaign.');window.setTimeout(()=>openCampaign(),0);
 }
 async function saveDraft(){if(!draft)return;const result=await act('draft',{id:draft.lead.id,subject:draft.subject,body:draft.body},'Draft updated.');if(result)setDraft(null);}
 async function approveOne(lead:Lead){const result=await act('approve',{ids:[lead.id]},data.gmailDemo?'Approval saved to sample data.':'Approved. Sending will follow the account schedule and limits.');if(result)setDraft(null);}
 async function saveGoal(){const amount=Number(goalDraft);if(!Number.isFinite(amount)||amount<=0){setToast('Enter a goal greater than zero.');return;}const result=await act('settings',{values:{goal:String(amount),goalCurrency:goalCurrencyDraft}},'Goal updated.');if(result)setGoalOpen(false);}
 async function openLead(lead:Lead){setSelected(lead);}
 async function openDraft(lead:Lead,reply=false){const latestReply=data.messages.find((message:any)=>message.direction==='inbound'&&String(message.leadId)===String(lead.id));setDraft({lead,subject:reply?`Re: ${latestReply?.subject||lead.subject||'Your note'}`:lead.subject||'',body:reply?'Thanks for getting back to me. I’d be happy to share a little more. What would be most useful to know?':lead.body||'',reply});}

 const phaseLabel=menu.find(item=>item.name===tab)?.phase||'TODAY';
 const navKeys:Record<string,keyof typeof import('@/i18n/messages').messages['en-US']>={Dashboard:'dashboard',Leads:'leads',Campaigns:'campaigns','AI Chat':'chat',Inbox:'inbox',Import:'import',Settings:'settings'};
 const phaseKeys:Record<string,keyof typeof import('@/i18n/messages').messages['en-US']>={WORKSPACE:'phaseWorkspace',PROSPECTS:'phaseProspects',OUTREACH:'phaseOutreach',ASSISTANT:'phaseAssistant',CONVERSATIONS:'phaseConversations',REVENUE:'phaseRevenue','LEAD INTAKE':'phaseIntake',SETUP:'phaseSetup'};
 const titleKeys:Record<Tab,keyof typeof import('@/i18n/messages').messages['en-US']>={HOJE:'titleToday',IMPORTAR:'importTitle',LEADS:'titleProspects',FILA:'titleCampaigns',CHAT:'titleChat',QUENTES:'titleInbox',FUNIL:'titleSales','CONFIGURAÇÃO FINAL':'titleSetup'};
 const introKeys:Record<Tab,keyof typeof import('@/i18n/messages').messages['en-US']>={HOJE:'introToday',IMPORTAR:'introImport',LEADS:'introLeads',FILA:'introCampaigns',CHAT:'introChat',QUENTES:'introInbox',FUNIL:'introSales','CONFIGURAÇÃO FINAL':'introSetup'};
 const pendingTasks=data.tasks.filter(task=>task.status==='open');
 const recent=data.activities.slice(0,7);
 const navCounts:Record<string,number>={FILA:queue.length,QUENTES:warm.length};

 return <div className="app-shell">
  {!online&&<div className="offline-banner" role="status">{translate(locale,'offline')}</div>}
  <aside className="sidebar">
   <button className="brand" onClick={()=>setTab('HOJE')}><span className="brand-symbol"><span> D </span></span><span><b>DEVREFRACT</b><small>PERSONAL OUTREACH</small></span></button>
   <button className="workspace-pill"><span className="workspace-dot"/><span><b>Adilson</b><small>Personal workspace</small></span><ChevronDown size={15}/></button>
   <div className="side-label">WORKSPACE</div>
   <nav className="side-nav">{menu.map(item=>{const Icon=item.icon;return <button key={item.name} className={`nav-item ${tab===item.name?'active':''}`} onClick={()=>{setTab(item.name);setQuery('');if(item.name!=='CHAT')setSelectedIds([]);}}><Icon size={17} strokeWidth={1.8}/><span>{translate(locale,navKeys[item.label])}</span>{navCounts[item.name]?<i>{navCounts[item.name]}</i>:null}</button>;})}</nav>
   <div className="sidebar-bottom">
    <div className="connection-card"><span className={`connection-light ${data.gmailDemo?'offline':''}`}/><div><b>{data.accounts.length?`${data.accounts.length} Gmail account${data.accounts.length===1?'':'s'}`:'Gmail not connected'}</b><small>{data.gmailDemo?'Connect an account':'Connected and encrypted'}</small></div><ChevronRight size={14}/></div>
    <div className="sidebar-profile"><span className="profile-avatar">A</span><span><b>Adilson</b><small>Devrefract workspace</small></span><span className="profile-dot"/></div>
   </div>
  </aside>

  <nav className="mobile-primary-nav" aria-label="Primary navigation">
   {[{name:'HOJE' as Tab,label:'today' as const,icon:LayoutDashboard},{name:'QUENTES' as Tab,label:'hot' as const,icon:Flame},{name:'FILA' as Tab,label:'queue' as const,icon:Mail},{name:'FUNIL' as Tab,label:'sales' as const,icon:Kanban}].map(item=>{const Icon=item.icon;return <button key={item.name} className={tab===item.name?'active':''} onClick={()=>{setMoreOpen(false);setTab(item.name);}}><Icon size={19}/><span>{translate(locale,item.label)}</span></button>})}
   <button className={moreOpen?'active':''} onClick={()=>setMoreOpen(value=>!value)}><MoreHorizontal size={19}/><span>{translate(locale,'more')}</span></button>
  </nav>
  {moreOpen&&<div className="mobile-more-backdrop" onClick={()=>setMoreOpen(false)}><section className="mobile-more-sheet" onClick={event=>event.stopPropagation()}><header><b>More</b><button onClick={()=>setMoreOpen(false)} aria-label="Close menu"><X size={19}/></button></header>{[{tab:'LEADS' as Tab,label:'Leads',icon:UsersRound},{tab:'FILA' as Tab,label:'Campaigns',icon:Mail},{tab:'CHAT' as Tab,label:'Ask Devi',icon:MessageCircle},{tab:'IMPORTAR' as Tab,label:'Import leads',icon:Upload},{tab:'CONFIGURAÇÃO FINAL' as Tab,label:'Settings',icon:Settings2}].map(item=>{const Icon=item.icon;return <button key={item.tab} onClick={()=>{setTab(item.tab);setMoreOpen(false);}}><Icon size={18}/>{item.label}<ArrowRight size={15}/></button>})}</section></div>}

  <main className="main-area">
   <header className="topbar"><div className="breadcrumbs"><span className="topbar-mark">D</span><b>{translate(locale,({HOJE:'today',IMPORTAR:'import',LEADS:'leads',FILA:'campaigns',CHAT:'chat',QUENTES:'inbox',FUNIL:'sales','CONFIGURAÇÃO FINAL':'settings'} as Record<string,keyof typeof import('@/i18n/messages').messages['en-US']>)[tab]||'today')}</b><span className="global-state"><i className={data.stopped?'stopped':data.gmailDemo?'paused':''}/>{data.stopped?'Parado':data.gmailDemo?'Em pausa':'A enviar'}</span></div><div className="top-actions"><button className={`stop-all global-stop ${data.stopped?'is-stopped':''}`} onClick={()=>void act(data.stopped?'resume':'stop',{},data.stopped?translate(locale,'resume'):'STOP ALL enabled. Pending jobs have been cancelled.')}><CircleStop size={15}/>{data.stopped?translate(locale,'resume'):'PARAR TUDO'}</button><button className="locale-toggle" onClick={()=>changeLocale(locale==='pt-PT'?'en-US':'pt-PT')} aria-label="Change interface language">{locale==='pt-PT'?'PT':'EN'}</button><button className="global-search" onClick={()=>{setPaletteOpen(true);setPaletteQuery('');}}><Search size={16}/><span>{translate(locale,'search')}</span><kbd>⌘ K</kbd></button><button className="top-icon" title="Sync inbox" onClick={()=>void act('sync-inbox',{},'Inbox sync queued.')}><Inbox size={17}/>{warm.length>0&&<i/>}</button><button className="top-avatar" aria-label="Open settings" onClick={()=>setTab('CONFIGURAÇÃO FINAL')}>A</button></div></header>

   <section className="page-heading"><div><div className="eyebrow"><span className="phase-mark">{translate(locale,phaseKeys[phaseLabel]||'phaseWorkspace')}</span><span className="live-dot"/> {tab==='HOJE'?translate(locale,'priorities'):tab==='CHAT'?translate(locale,'assistantLabel'):tab==='CONFIGURAÇÃO FINAL'?translate(locale,'setupChecklist'):translate(locale,'workspaceLabel')}</div><h1>{translate(locale,titleKeys[tab])}</h1><p>{translate(locale,introKeys[tab])}</p></div><div className="heading-actions">{data.demo&&<span className="demo-chip"><span/>{translate(locale,'sample')}</span>}</div></section>

   {loading?<SkeletonScreen/>:<>
    {tab==='HOJE'&&<>
     <section className="command-hero"><div className="hero-copy"><div className="hero-kicker"><Zap size={14}/> TODAY’S PLAN <span>·</span> {new Intl.DateTimeFormat('en-US',{weekday:'long',day:'numeric',month:'long'}).format(new Date()).toUpperCase()}</div><h2>Close the next<br/><em>good deal.</em></h2><p>{pendingTasks.length?`${pendingTasks.length} open tasks · ${warm.length} interested conversations need your attention.`:'Your workspace is ready. Repetitive work stays in the background; you decide what happens next.'}</p><div className="hero-buttons"><button className="button-primary" onClick={()=>warm.length?setTab('QUENTES'):setTab('LEADS')}>{warm.length?'Reply to interested leads':'Review prospects'} <ArrowRight size={15}/></button><button className="button-ghost" onClick={openCampaign}>Prepare campaign <Command size={14}/></button></div></div><div className="hero-goal"><span className="glass-line"/><div className="countdown"><small>DEADLINE · DEC 6</small><b>{daysLeft.toString().padStart(2,'0')}</b><span>DAYS</span></div><div className="goal-divider"/><div className="goal-copy"><small>GOAL PROGRESS</small><b>{money(closedTarget,goalCurrency)}</b><span>of {money(goal,goalCurrency)}</span><div className="goal-track"><i style={{width:`${progress}%`}}/></div><button onClick={()=>{setGoalDraft(String(goal));setGoalCurrencyDraft(goalCurrency);setGoalOpen(true);}}>Edit goal <ArrowUpRight size={13}/></button></div></div><div className="hero-grid-glow"/></section>
     <div className="metric-grid"><Metric icon={UsersRound} label="PROSPECTS" value={leads.length.toString()} meta={`${leads.filter(l=>l.email).length} with email`} tone="blue"/><Metric icon={Flame} label="INTERESTED REPLIES" value={warm.length.toString().padStart(2,'0')} meta="explicit buying interest" tone="amber"/><Metric icon={Mail} label="NEEDS REVIEW" value={queue.length.toString().padStart(2,'0')} meta="personalized drafts" tone="violet"/><Metric icon={Send} label="SENT TODAY" value={data.sentToday.toString()} meta={`${data.accounts.reduce((sum:number,a:any)=>sum+a.dailyCap,0)||100} warmed capacity`} tone="cyan"/></div>
     <div className="dashboard-grid"><section className="panel attention-panel"><PanelHeader label="NEEDS YOUR ATTENTION" title="Next actions" action="View inbox" onClick={()=>setTab('QUENTES')}/><div className="priority-list">
       <Priority icon={Flame} tone="amber" title="Reply to interested prospects" sub={warm[0]?`${warm[0].name} · ${warm[0].summary||'Interest received'}`:'No interested replies right now'} count={warm.length} onClick={()=>setTab('QUENTES')}/>
       <Priority icon={Mail} tone="violet" title="Review prepared emails" sub={queue[0]?`${queue[0].name} · ready for approval`:'Your review queue is clear'} count={queue.length} onClick={()=>setTab('FILA')}/>
       <Priority icon={CalendarClock} tone="cyan" title="Continue prospecting" sub={`${leads.filter(l=>l.status==='Novo'&&l.email).length} new prospects with an email`} count={leads.filter(l=>l.status==='Novo'&&l.email).length} onClick={()=>setTab('LEADS')}/>
      </div></section><section className="panel pipeline-panel"><PanelHeader label={`GOAL · ${deadline}`} title="Progress toward your goal" action="Open sales" onClick={()=>setTab('FUNIL')}/><div className="pipeline-amount"><b>{money(closedTarget,goalCurrency)}</b><span>/ {money(goal,goalCurrency)}</span><strong>{Math.round(progress)}%</strong></div><div className="goal-track"><i style={{width:`${progress}%`}}/></div><div className="mini-stages">{[['Contacted',contacted],['Interested',warm.length],['Demo sent',leads.filter(l=>l.status==='Demo enviada').length],['Won',leads.filter(l=>l.status==='Fechado').length]].map(([label,count])=><div key={String(label)}><small>{label}</small><b>{count}</b></div>)}</div></section></div>
     <div className="dashboard-grid lower-grid"><section className="panel task-panel"><PanelHeader label="TODAY’S PLAN" title="Your execution list" action="View sales" onClick={()=>setTab('FUNIL')}/>{pendingTasks.length?pendingTasks.slice(0,5).map(task=><TaskRow key={task.id} task={task} lead={leads.find(l=>l.id===task.leadId)} onOpen={()=>{const lead=leads.find(l=>l.id===task.leadId);if(lead)setSelected(lead);}} onDone={()=>void act('task-done',{id:task.id},'Task completed.')}/>):<div className="empty-inline"><Check size={16}/> Your list is clear. Import prospects or review new opportunities.</div>}</section><section className="panel activity-panel"><PanelHeader label="LIVE ACTIVITY" title="What the workspace is doing" action="Sync inbox" onClick={()=>void act('sync-inbox',{},'Inbox sync queued.')}/><ActivityFeed items={recent.slice(0,5)}/></section></div>
     <section className="panel recent-panel"><PanelHeader label="RECENT ACTIVITY" title="Recently updated prospects" action="Open prospects" onClick={()=>setTab('LEADS')}/><LeadTable leads={leads.slice(0,5)} onOpen={setSelected} onResearch={lead=>void act('research',{id:lead.id},`Research queued for ${lead.name}.`)} compact/></section>
    </>}

    {tab==='CHAT'&&<ChatWorkspace messages={chatMessages} input={chatInput} setInput={setChatInput} busy={chatBusy} onSend={()=>void sendChat()} onExecute={proposal=>void executeChatProposal(proposal)}/>}
    {tab==='IMPORTAR'&&<ImportView csv={csv} csvName={csvName} niche={csvNiche} mapping={csvMap} onMapping={(key,value)=>setCsvMap(old=>({...old,[key]:value}))} onFile={selectFile} onNiche={setCsvNiche} onImport={()=>void importCsv()} busy={busy}/>}

    {tab==='QUENTES'&&<InboxView messages={inboxMessages} leads={leads} onReply={lead=>void openDraft(lead,true)} onOpen={setSelected} onSync={()=>void act('sync-inbox',{},'Inbox sync queued.')}/>}
    {(['LEADS','FILA'].includes(tab))&&<section className="panel list-panel"><div className="list-toolbar"><div className="list-filters"><label className="filter-search"><Search size={15}/><input placeholder="Search prospects, email, city, or evidence" value={query} onChange={e=>setQuery(e.target.value)}/></label><label className="select-wrap"><Filter size={13}/><select value={city} onChange={e=>setCity(e.target.value)}>{cities.map(v=><option key={v}>{v}</option>)}</select><ChevronDown size={12}/></label><label className="select-wrap"><select value={niche} onChange={e=>setNiche(e.target.value)}>{niches.map(v=><option key={v}>{v}</option>)}</select><ChevronDown size={12}/></label></div><div className="list-actions">{tab==='FILA'&&<label className="mode-toggle"><span>{data.settings.auto==='1'?'AUTO PILOT':'REVIEW'}</span><input type="checkbox" checked={data.settings.auto==='1'} onChange={e=>{const value=e.target.checked?'1':'0';changeSetting('auto',value);void act('settings',{values:{auto:value}},'Sending mode saved.');}}/><i/></label>}{tab==='LEADS'&&<button className="button-primary" onClick={openCampaign} disabled={busy}><Sparkles size={15}/> Prepare campaign</button>}</div></div><div className="table-meta"><span><b>{shown.length}</b> {tab==='FILA'?'drafts to review':'prospects shown'}</span><div>{tab==='LEADS'&&<><button onClick={()=>setSelectedIds(shown.map(l=>l.id))}>Select visible</button><button onClick={()=>setSelectedIds([])}>Clear</button><span>{selectedIds.length} selected</span></>}</div></div><LeadTable leads={shown} selectedIds={selectedIds} onSelect={id=>setSelectedIds(old=>old.includes(id)?old.filter(x=>x!==id):[...old,id])} onOpen={setSelected} onResearch={lead=>void act('research',{id:lead.id},`Research queued for ${lead.name}.`)} onReview={lead=>void openDraft(lead)} onReply={lead=>void openDraft(lead,true)} mode={tab}/>{shown.length===0&&<div className="empty-state"><span><Search size={20}/></span><b>{tab==='FILA'?'No drafts to review':'No prospects found'}</b><p>{tab==='LEADS'?'Import a CSV or adjust your search.':'New activity will appear here.'}</p>{tab==='LEADS'&&<button className="button-secondary" onClick={()=>setTab('IMPORTAR')}>Import CSV</button>}</div>}</section>}

    {tab==='FUNIL'&&<FunnelView leads={leads} goal={goal} currency={goalCurrency} closed={closedTarget} progress={progress} campaigns={data.campaigns} sent={data.messages} fx={data.fx} onStage={(lead,status,value)=>void act('stage',{id:lead.id,status,value},`${lead.name} movido para ${status}.`)} onOpen={setSelected} onGoal={()=>{setGoalDraft(String(goal));setGoalCurrencyDraft(goalCurrency);setGoalOpen(true);}} onRefreshFx={()=>void act('refresh-fx',{currency:goalCurrency},'Exchange rate updated.')}/>}

    {tab==='CONFIGURAÇÃO FINAL'&&<SetupView data={data} onSetting={changeSetting} models={models} setModels={setModels} email={selfEmail} setEmail={setSelfEmail} accountId={selfAccountId} setAccountId={setSelfAccountId} onSave={()=>void saveSettings()} onTest={provider=>void act('test-ai',{provider},`Queued ${provider} model test.`)} onSelfSend={()=>void act('self-test',{email:selfEmail,accountId:selfAccountId},data.gmailDemo?'Sample email queued.':'Sample email queued for delivery.')} onConnect={(id)=>window.location.assign(`/api/auth${id?`?accountId=${encodeURIComponent(id)}`:''}`)} onDisconnect={id=>void act('disconnect-account',{id},'Gmail account disconnected.')}/>}
   </>}
  </main>

  <aside className={`right-rail ${chatOpen?'chat-mode':''}`}>
   {chatOpen?<><div className="rail-header"><div><span className="rail-mark"><Sparkles size={15}/></span><div><b>Devi</b><small><i className="live-dot"/> Local workspace</small></div></div><button className="icon-plain" aria-label="Close Devi" onClick={()=>setChatOpen(false)}><X size={17}/></button></div><div className="chat-context"><span><Activity size={15}/></span><div><b>Workspace context</b><small>{leads.length} prospects · {warm.length} interested · {queue.length} drafts in queue</small></div></div><div className="chat-stream">{chatMessages.map((message,index)=><div className={`chat-message ${message.role}`} key={index}>{message.role==='assistant'&&<span className="chat-mark"><Sparkles size={12}/></span>}<div><p>{message.text}</p>{message.proposal&&<div className="proposal-card"><b>{message.proposal.count} prospects selected</b><small>Prepare drafts for review or confirm Auto Pilot in campaign settings.</small><button onClick={()=>void executeChatProposal(message.proposal!)}>Create campaign <ArrowRight size={13}/></button></div>}</div></div>)}{chatBusy&&<div className="chat-message assistant"><span className="chat-mark"><Sparkles size={12}/></span><p className="typing">Checking your workspace <i/><i/><i/></p></div>}</div><div className="quick-prompts"><small>QUICK PROMPTS</small>{['How many prospects have an email?','Show interested conversations','Which segment replies best?'].map((text,index)=><button key={text} onClick={()=>setChatInput(text)}>{[<Mail size={13} key="m"/>,<Flame size={13} key="f"/>,<TrendingUp size={13} key="t"/>][index]}<span>{text}</span><ArrowRight size={13}/></button>)}</div><form className="chat-compose" onSubmit={event=>{event.preventDefault();void sendChat();}}><textarea placeholder="Ask Devi about your workspace…" value={chatInput} onChange={event=>setChatInput(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();void sendChat();}}}/><div><small>Enter to send · Shift + Enter for a new line</small><button disabled={!chatInput.trim()||chatBusy} aria-label="Send message"><Send size={14}/></button></div></form><div className="rail-foot"><ShieldCheck size={12}/> Sending and bulk changes require your confirmation.</div></>:<><div className="rail-header"><div><span className="rail-mark"><Activity size={15}/></span><div><b>Outreach assistant</b><small><i className="live-dot"/> {data.stopped?'PAUSED':data.gmailDemo?'Using sample data':'Workspace connected'}</small></div></div><button className="icon-plain" title="Open Devi" onClick={()=>setChatOpen(true)}><Sparkles size={16}/></button></div><div className="rail-section"><div className="rail-section-head"><span>LIVE ACTIVITY</span><span className="live-chip"><i/> LIVE</span></div><ActivityFeed items={recent}/></div><div className="rail-section rail-tasks"><div className="rail-section-head"><span>NEEDS YOUR ATTENTION</span><button onClick={()=>setTab('HOJE')}>View all <ArrowRight size={12}/></button></div>{pendingTasks.slice(0,4).map(task=><TaskRow key={task.id} task={task} lead={leads.find(l=>l.id===task.leadId)} onOpen={()=>{const lead=leads.find(l=>l.id===task.leadId);if(lead)setSelected(lead);}} onDone={()=>void act('task-done',{id:task.id},'Task completed.')}/>)}{!pendingTasks.length&&<p className="rail-empty">No urgent tasks right now.</p>}</div><button className="rail-chat-cta" onClick={()=>setChatOpen(true)}><Sparkles size={15}/> Ask Devi <ArrowRight size={14}/></button></>}
  </aside>

  {!chatOpen&&<button className="mobile-chat-fab" onClick={()=>setChatOpen(true)}><Sparkles size={16}/> Devi</button>}

  {selected&&<LeadDrawer lead={selected} onClose={()=>setSelected(null)} onResearch={()=>void act('research',{id:selected.id},`Research started for ${selected.name}.`)} onDraft={()=>void openDraft(selected)} onReply={()=>void openDraft(selected,true)} onBrief={async()=>{const result=await act('demo-brief',{id:selected.id},'Demo brief prepared.');if(result)setSelected({...selected,demoBrief:result.brief});}} onStage={(status)=>void act('stage',{id:selected.id,status},`Stage updated: ${status}.`)} onSuppress={()=>void act('suppress',{email:selected.email,reason:'Manual request',source:'Prospect profile'},'Address added to global suppression.')} onOpenTask={(taskId)=>{const task=data.tasks.find(t=>t.id===taskId);if(task)setToast(task.title);}}/>}
  {draft&&<DraftModal draft={draft} onChange={setDraft} onClose={()=>setDraft(null)} onSave={saveDraft} onApprove={()=>void approveOne(draft.lead)} onReplySend={async()=>{const result=await act('reply',{id:draft.lead.id,reply:draft.body},'Resposta aprovada e agendada dentro dos limites.');if(result)setDraft(null);}}/>}
  {campaignOpen&&<CampaignModal preview={preview} mode={campaignMode} setMode={setCampaignMode} accountId={campaignAccountId} setAccountId={setCampaignAccountId} onClose={()=>{setCampaignOpen(false);setPreview(null);}} onLaunch={()=>void launchCampaign()}/>}
  {goalOpen&&<GoalModal value={goalDraft} setValue={setGoalDraft} currency={goalCurrencyDraft} setCurrency={setGoalCurrencyDraft} onClose={()=>setGoalOpen(false)} onSave={()=>void saveGoal()}/>}
  {paletteOpen&&<CommandPalette query={paletteQuery} setQuery={setPaletteQuery} onClose={()=>setPaletteOpen(false)} onRun={command=>{setPaletteOpen(false);if(command==='campaign')openCampaign();else if(command==='sync')void act('sync-inbox',{},'Inbox sync queued.');else if(command==='chat')setTab('CHAT');else setTab(command as Tab);}}/>}
  {toast&&<div className="toast" role="status"><span className="toast-mark"><Sparkles size={14}/></span><span>{toast}</span><button onClick={()=>setToast('')}><X size={14}/></button></div>}
 </div>;
}

function Metric({icon:Icon,label,value,meta,tone}:{icon:any;label:string;value:string;meta:string;tone:string}){return <article className="metric-card"><div className={`metric-icon ${tone}`}><Icon size={16}/></div><div className="metric-value"><span>{label}</span><b>{value}</b><small>{meta}</small></div><ArrowUpRight className="metric-arrow" size={15}/></article>;}
function PanelHeader({label,title,action,onClick}:{label:string;title:string;action?:string;onClick?:()=>void}){return <div className="panel-header"><div><span className="section-label">{label}</span><h2>{title}</h2></div>{action&&<button className="panel-link" onClick={onClick}>{action}<ArrowRight size={13}/></button>}</div>;}
function Priority({icon:Icon,tone,title,sub,count,onClick}:{icon:any;tone:string;title:string;sub:string;count:number;onClick:()=>void}){return <button className="priority-row" onClick={onClick}><span className={`priority-icon ${tone}`}><Icon size={16}/></span><span className="priority-copy"><b>{title}</b><small>{sub}</small></span><strong>{String(count).padStart(2,'0')}</strong><ChevronRight size={15}/></button>;}
function ActivityFeed({items}:{items:ActivityItem[]}){return <div className="activity-feed">{items.length?items.map(item=><div className="feed-row" key={item.id}><span className={`feed-icon ${item.kind}`}><FeedIcon kind={item.kind}/></span><div><b>{item.message}</b><small>{dateTime(item.createdAt)}</small></div></div>):<div className="feed-empty"><Activity size={17}/><span>Waiting for activity.</span></div>}</div>;}
function FeedIcon({kind}:{kind:string}){if(kind==='reply'||kind==='reply-sent')return <MessageCircle size={13}/>;if(kind==='send'||kind==='campaign')return <Send size={13}/>;if(kind==='research')return <FileSearch size={13}/>;if(kind==='warning'||kind==='stop')return <CircleStop size={13}/>;if(kind==='import')return <Upload size={13}/>;return <Sparkles size={13}/>;}
function TaskRow({task,lead,onOpen,onDone}:{task:Task;lead?:Lead;onOpen:()=>void;onDone:()=>void}){return <div className="task-row"><button className="task-open" onClick={onOpen}><span className="task-check"><Clock3 size={13}/></span><span><b>{task.title}</b><small>{lead?.name||task.kind} · {task.dueAt?dateTime(task.dueAt):'sem prazo'}</small></span></button><button className="task-done" title="Complete task" onClick={onDone}><Check size={14}/></button></div>;}
function SkeletonScreen(){return <div className="skeleton-screen"><div className="skeleton hero-skeleton"/><div className="skeleton metrics-skeleton"/><div className="skeleton panel-skeleton"/></div>;}

function ChatWorkspace({messages,input,setInput,busy,onSend,onExecute}:{messages:ChatMessage[];input:string;setInput:(value:string)=>void;busy:boolean;onSend:()=>void;onExecute:(proposal:NonNullable<ChatMessage['proposal']>)=>void}){
 return <section className="panel chat-workspace"><div className="chat-workspace-top"><span className="rail-mark"><Sparkles size={16}/></span><div><b>Devi · workspace assistant</b><small>Reads workspace data and proposes actions for your approval.</small></div><span className="chat-safe"><ShieldCheck size={13}/> Actions stay in your control</span></div><div className="chat-workspace-stream">{messages.map((message,index)=><div className={`chat-message ${message.role}`} key={index}><div className="chat-workspace-bubble"><p>{message.text}</p>{message.results&&message.results.length>0&&<div className="chat-result-list">{message.results.map(result=><div key={result.id}><b>{result.name||'Prospect'}</b><span>Score {result.score||0}</span>{result.synthetic&&<small>Sample</small>}</div>)}</div>}{message.proposal&&<div className="proposal-card"><b>{message.proposal.count} prospects selected</b><small>{message.proposal.type==='research'?'Queue website research for real prospects.':'Review the audience and campaign settings before launch.'}</small><button onClick={()=>onExecute(message.proposal!)}>{message.proposal.type==='research'?'Queue research':'Review campaign'} <ArrowRight size={13}/></button></div>}</div></div>)}{busy&&<div className="chat-message assistant"><div className="chat-workspace-bubble typing">Checking workspace data <i/><i/><i/></div></div>}</div><div className="chat-workspace-suggestions">{['How many prospects have an email?','Show today’s replies','Research the 20 highest-scored prospects'].map(text=><button key={text} onClick={()=>setInput(text)}>{text}<ArrowRight size={12}/></button>)}</div><form className="chat-workspace-compose" onSubmit={event=>{event.preventDefault();onSend();}}><textarea aria-label="Message Devi" placeholder="Ask about your prospects or sales activity…" value={input} onChange={event=>setInput(event.target.value)} onKeyDown={event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();onSend();}}}/><button className="button-primary" disabled={!input.trim()||busy}><Send size={15}/> Send</button></form></section>;
}

function InboxView({messages,leads,onReply,onOpen,onSync}:{messages:any[];leads:Lead[];onReply:(lead:Lead)=>void;onOpen:(lead:Lead)=>void;onSync:()=>void}){
 const [filter,setFilter]=useState('all');const visible=messages.filter(message=>filter==='all'||message.classification===filter);
 return <section className="panel inbox-workspace"><div className="inbox-toolbar"><div><span className="section-label">CONVERSATIONS</span><h2>{messages.length} replies</h2><p>Replies stay linked to their lead and Gmail account when a match is available.</p></div><button className="button-secondary" onClick={onSync}><Inbox size={14}/> Sync inbox</button></div><div className="inbox-filters">{[['all','All'],['interested','Interested'],['question','Questions'],['not_interested','Objections'],['opt_out','Opt-outs']].map(([key,label])=><button key={key} className={filter===key?'active':''} onClick={()=>setFilter(key)}>{label}{key==='all'&&<span>{messages.length}</span>}</button>)}</div>{visible.length?<div className="inbox-message-list">{visible.map((message:any)=>{const lead=leads.find(item=>String(item.id)===String(message.leadId));return <article className="inbox-message" key={message.id} onClick={()=>lead&&onOpen(lead)}><div className="inbox-avatar">{(lead?.name||message.sender||'?').slice(0,1).toUpperCase()}</div><div className="inbox-message-main"><div className="inbox-message-heading"><b>{lead?.name||message.sender||'Unknown sender'}</b><time>{dateTime(message.receivedAt)}</time></div><div className="inbox-message-subject">{message.subject||'No subject'} <span className={`classification-pill ${message.classification||'other'}`}>{String(message.classification||'other').replaceAll('_',' ')}</span>{message.synthetic&&<span className="synthetic-pill">SAMPLE</span>}</div><p>{message.body||'Message content is unavailable.'}</p><small>{lead?.email||message.sender||'No linked lead'}{lead?.city?` · ${lead.city}`:''}</small></div><div className="inbox-message-action">{lead&&message.classification!=='opt_out'&&<button className="small-action warm-action" onClick={event=>{event.stopPropagation();onReply(lead);}}>Reply <MessageCircle size={13}/></button>}</div></article>;})}</div>:<div className="inbox-empty"><span><Inbox size={22}/></span><b>{messages.length?'No replies match this filter.':'Your inbox is clear.'}</b><p>Sync Gmail to check for new conversations. Replies and opt-outs will appear here.</p><button className="button-secondary" onClick={onSync}>Sync inbox</button></div>}</section>;
}

function LeadTable({leads,onOpen,onResearch,onReview,onReply,mode,selectedIds=[],onSelect=()=>{},compact=false}:{leads:Lead[];onOpen:(lead:Lead)=>void;onResearch:(lead:Lead)=>void;onReview?:(lead:Lead)=>void;onReply?:(lead:Lead)=>void;mode?:string;selectedIds?:EntityId[];onSelect?:(id:EntityId)=>void;compact?:boolean}){
 const action=(lead:Lead)=>mode==='FILA'&&onReview?<button className="small-action" onClick={(event:any)=>{event.stopPropagation();onReview(lead);}}>Review <ArrowRight size={13}/></button>:mode==='QUENTES'&&onReply?<button className="small-action warm-action" onClick={(event:any)=>{event.stopPropagation();onReply(lead);}}>Reply <MessageCircle size={13}/></button>:<button className="row-open" aria-label={`Open ${lead.name}`} onClick={(event:any)=>{event.stopPropagation();onOpen(lead);}}><ChevronRight size={15}/></button>;
 return <div className={`lead-table-wrap ${compact?'compact':''}`}><table className="lead-table"><thead><tr>{!compact&&mode==='LEADS'&&<th className="check-col"/>}<th>LEAD</th><th>SCORE</th><th>SIGNAL / EMAIL</th><th>STAGE</th><th>NEXT ACTION</th><th/></tr></thead><tbody>{leads.map(lead=><tr key={lead.id} onClick={()=>onOpen(lead)}>{!compact&&mode==='LEADS'&&<td className="check-col"><input aria-label={`Select ${lead.name}`} type="checkbox" checked={selectedIds.includes(lead.id)} onClick={event=>event.stopPropagation()} onChange={()=>onSelect(lead.id)}/></td>}<td><span className="lead-person"><i>{lead.name.slice(0,1).toUpperCase()}</i><span><b>{lead.name}</b><small>{lead.niche} · {lead.city||'Unknown city'}</small></span></span></td><td><span className={`score-pill ${lead.score>=70?'high':lead.score>=50?'mid':''}`}><Zap size={12}/>{lead.score||0}</span></td><td><span className="lead-signal">{lead.website?<a href={lead.website} target="_blank" rel="noreferrer" onClick={event=>event.stopPropagation()}><Globe2 size={12}/>{lead.siteStatus==='Só rede social'?'Social profile':'Website'}</a>:<button onClick={event=>{event.stopPropagation();onResearch(lead);}}><FileSearch size={12}/> Research</button>}<small>{lead.email||'No email found'}</small></span></td><td><span className={`stage-pill stage-${lead.status.toLowerCase().replaceAll(' ','-')}`}><i/>{statusLabel(lead.status)}</span></td><td><span className="evidence-cell">{lead.evidence?.[0]?.observation||'No verified signals yet'}</span></td><td className="table-action">{action(lead)}</td></tr>)}</tbody></table><div className="lead-mobile-list">{leads.map(lead=><article className="lead-mobile-card" key={lead.id} onClick={()=>onOpen(lead)}>{mode==='LEADS'&&<input aria-label={`Select ${lead.name}`} type="checkbox" checked={selectedIds.includes(lead.id)} onClick={(event)=>event.stopPropagation()} onChange={()=>onSelect(lead.id)}/>}<div className="lead-mobile-head"><span className="lead-person"><i>{lead.name.slice(0,1).toUpperCase()}</i><span><b>{lead.name}</b><small>{lead.niche} · {lead.city||'Unknown city'}</small></span></span><span className="score-pill"><Zap size={12}/>{lead.score||0}</span></div><span className="stage-pill"><i/>{statusLabel(lead.status)}</span><p>{lead.evidence?.[0]?.observation||lead.email||'No verified research yet'}</p><div className="lead-mobile-actions"><small>{lead.email||'No email'}</small>{action(lead)}</div></article>)}</div></div>;
}

function ImportView({csv,csvName,niche,mapping,onMapping,onFile,onNiche,onImport,busy}:{csv:string;csvName:string;niche:string;mapping:Record<string,string>;onMapping:(key:string,value:string)=>void;onFile:(file?:File)=>void;onNiche:(value:string)=>void;onImport:()=>void;busy:boolean}){
 const rows=csv.split(/\r?\n/).filter(Boolean),headers=rows[0]?.split(/[;,\t]/)||[];
 const fields=[['name','Business name'],['email','Email'],['website','Website'],['city','City'],['state','State']];
 return <section className="panel import-panel"><div className="import-heading"><span className="import-number">01</span><div><span className="section-label">PHASE 1 · LEAD INTAKE</span><h2>Import your Apify list</h2><p>Map fields, catch duplicates, and validate the list before adding prospects.</p></div></div><label className={`dropzone ${csv?'has-file':''}`}><input type="file" accept=".csv,text/csv" onChange={event=>onFile(event.target.files?.[0])}/><span className="drop-icon"><Upload size={20}/></span><b>{csvName||'Drop a CSV here or choose a file'}</b><small>{csv?`${Math.max(0,rows.length-1)} rows · ${headers.length} columns detected`:'CSV · UTF-8 · Apify exports supported'}</small>{csv&&<span className="drop-ok"><Check size={13}/> Ready to review</span>}</label>{csv&&<div className="csv-mapping">{fields.map(([key,label])=><label key={key}>{label}<select value={mapping[key]||''} onChange={e=>onMapping(key,e.target.value)}><option value="">Auto-detect</option>{headers.map((header,index)=><option key={index} value={header}>{header}</option>)}</select></label>)}</div>}<div className="import-fields"><label>Industry / segment<input value={niche} onChange={event=>onNiche(event.target.value)} placeholder="e.g. med spas"/></label><div className="english-note">Outreach copy is written in American English. Only U.S. businesses with a recognizable state are imported.</div></div>{csv&&<div className="csv-preview"><div className="preview-title"><span>PREVIEW</span><b>{headers.slice(0,8).join(' · ')}</b></div><div className="preview-table">{rows.slice(0,4).map((row,index)=><div key={index}>{row.split(/[;,\t]/).slice(0,6).map((value,cell)=><span key={cell}>{value||'—'}</span>)}</div>)}</div></div>}<div className="import-footer"><span><ShieldCheck size={14}/> Duplicate emails and websites are skipped.</span><button className="button-primary" disabled={!csv||busy} onClick={onImport}><Upload size={15}/> Import prospects <ArrowRight size={14}/></button></div></section>;
}

function FunnelView({leads,goal,currency,closed,progress,campaigns,sent,fx,onStage,onOpen,onGoal,onRefreshFx}:{leads:Lead[];goal:number;currency:string;closed:number;progress:number;campaigns:any[];sent:any[];fx:any;onStage:(lead:Lead,status:string,value?:number)=>void;onOpen:(lead:Lead)=>void;onGoal:()=>void;onRefreshFx:()=>void}){
 const active=['Novo','Contactado','Respondeu','Quente','Demo enviada','Proposta','Fechado','Perdido'];
 const ab=campaigns.filter(c=>c.kind==='outbound').slice(0,3).map(c=>{
  const rows=sent.filter((m:any)=>m.campaignId===c.id&&m.direction==='outbound');
  const positive=sent.filter((m:any)=>m.campaignId===c.id&&m.direction==='inbound'&&m.classification==='interested');
  const sentA=rows.filter((m:any)=>m.variant==='A').length,sentB=rows.filter((m:any)=>m.variant==='B').length;
  const hotA=positive.filter((m:any)=>m.variant==='A').length,hotB=positive.filter((m:any)=>m.variant==='B').length;
  return {...c,sentA,sentB,hotA,hotB};
 });
 const columns=[['Novo','Contactado'],['Respondeu','Quente'],['Demo enviada','Proposta'],['Fechado','Perdido']];
 return <div className="funnel-page"><div className="funnel-summary panel"><div><span className="section-label">CLOSED REVENUE</span><b>{money(closed,currency)}</b></div><div><span className="section-label">GOAL</span><b>{money(goal,currency)}</b><button onClick={onGoal}>Edit <ArrowUpRight size={12}/></button></div><div className="funnel-goal"><div><span>{Math.round(progress)}% complete</span><span>{fx?.rateDate?`FX · ${fx.rateDate}`:'FX rate unavailable'}</span></div><div className="goal-track"><i style={{width:`${progress}%`}}/></div><button onClick={onRefreshFx}>Refresh exchange rate <ArrowRight size={12}/></button></div></div><div className="funnel-columns">{columns.map((group,index)=><div className="funnel-column" key={index}><header><span className={`column-dot dot-${index}`}/><b>{group.map(statusLabel).join(' / ')}</b><i>{leads.filter(lead=>group.includes(lead.status)).length}</i></header>{leads.filter(lead=>group.includes(lead.status)).map(lead=><article className="funnel-card" key={lead.id} onClick={()=>onOpen(lead)}><div className="funnel-card-top"><span className="score-pill"><Zap size={11}/>{lead.score||0}</span><button onClick={event=>{event.stopPropagation();onOpen(lead);}}><MoreHorizontal size={16}/></button></div><b>{lead.name}</b><small>{lead.niche} · {lead.city}</small><div className="funnel-card-bottom"><span>{lead.email||'No email'}</span><b>{lead.value?money(lead.value,'EUR'):''}</b></div><select aria-label={`Move ${lead.name}`} value={lead.status} onClick={event=>event.stopPropagation()} onChange={event=>{const value=event.target.value==='Fechado'?Number(prompt('Closed value in EUR:',String(lead.value||0))||0):undefined;onStage(lead,event.target.value,value);}}>{stages.map(stage=><option key={stage} value={stage}>{statusLabel(stage)}</option>)}</select></article>)}</div>)}</div><section className="panel ab-panel"><PanelHeader label="LEARNING · A/B" title="Subjects that earn replies"/><div className="ab-table"><div><span>CAMPAIGN</span><span>VARIANT A</span><span>VARIANT B</span><span>SIGNAL</span></div>{ab.length?ab.map(c=><div key={c.id}><b>{c.name}</b><span>{c.sentA} sent · {c.hotA} interested</span><span>{c.sentB} sent · {c.hotB} interested</span><strong>{c.sentA+c.sentB<20?'Collecting data':c.hotA>c.hotB?'A is ahead':c.hotB>c.hotA?'B is ahead':'No clear leader'}</strong></div>):<div className="ab-empty">Results will appear after your first campaign. The app won’t change your copy without showing the data.</div>}</div></section></div>;
}

function SetupView({data,onSetting,models,setModels,email,setEmail,accountId,setAccountId,onSave,onTest,onSelfSend,onConnect,onDisconnect}:{data:AppData;onSetting:(key:string,value:string)=>void;models:{groq:string;diagnosis:string;chat:string;reviewer:string;nvidia:string;huggingface:string};setModels:(v:{groq:string;diagnosis:string;chat:string;reviewer:string;nvidia:string;huggingface:string})=>void;email:string;setEmail:(v:string)=>void;accountId:string;setAccountId:(v:string)=>void;onSave:()=>void;onTest:(provider:string)=>void;onSelfSend:()=>void;onConnect:(id?:string)=>void;onDisconnect:(id:string)=>void}){
 const callbackOrigin=process.env.NEXT_PUBLIC_APP_URL||(typeof window!=='undefined'?window.location.origin:'');
 const callbackUri=callbackOrigin?new URL('/api/auth/callback',callbackOrigin).toString():'Set NEXT_PUBLIC_APP_URL in Vercel';
 const connectedAccounts=data.accounts.filter((account:any)=>['connected','Ligada'].includes(account.status));const connected=connectedAccounts.length;
 const flags=[Boolean(data.settings.googleClientIdConfigured==='true'&&data.settings.googleClientSecretConfigured==='true'),connected>=2,Boolean(data.settings.groqKeyConfigured==='true'),Boolean(data.settings.nvidiaKeyConfigured==='true'),data.settings.groqTestOk==='true'&&data.settings.nvidiaTestOk==='true'&&(data.settings.huggingfaceKeyConfigured!=='true'||data.settings.huggingfaceTestOk==='true'),data.settings.selfTestSent==='true',Boolean(data.settings.notificationEmail||'lopesadilson948@gmail.com')];
 const steps=[
  {n:1,title:'Google Cloud & OAuth',description:'Create a Google Cloud project, enable Gmail API, then create a Web OAuth client.',fields:<><div className="setup-grid"><label>Client ID<input type="password" autoComplete="off" value={data.settings.googleClientId||''} onChange={e=>onSetting('googleClientId',e.target.value)} placeholder={data.settings.googleClientIdConfigured==='true'?'Saved securely':'...apps.googleusercontent.com'}/></label><label>Client secret<input type="password" autoComplete="new-password" value={data.settings.googleClientSecret||''} onChange={e=>onSetting('googleClientSecret',e.target.value)} placeholder={data.settings.googleClientSecretConfigured==='true'?'Saved securely':'OAuth client secret'}/></label></div><label className="setup-field">Google login allowlist · one email per line<textarea rows={2} value={Array.isArray(data.settings.allowedEmails)?data.settings.allowedEmails.join('\n'):String(data.settings.allowedEmails||'lopesadilson948@gmail.com')} onChange={e=>onSetting('allowedEmails',e.target.value.split(/[\n,;]/).map(value=>value.trim().toLowerCase()).filter(Boolean).join(','))}/></label><div className="callback-uri">Authorized redirect URI <code>{callbackUri}</code></div></>},
  {n:2,title:'Connect Gmail accounts',description:'Connect up to five accounts. Each account has its own health and daily cap.',fields:<><div className="account-list">{data.accounts.map((account:any,index:number)=><div key={account.id} className="account-chip"><Mail size={13}/><b>Gmail {index+1}</b><small>{account.email}</small><i>{account.status}</i><em>{account.sentToday||0}/{account.dailyCap||100} today</em><button onClick={()=>onConnect(String(account.id))}>Reconnect</button><button onClick={()=>onDisconnect(String(account.id))}>Disconnect</button></div>)}</div><button className="google-button" onClick={()=>onConnect()} disabled={connected>=5}><GoogleMark/> Sign in with Google {connected?`· connect account ${connected+1}`:''}<ArrowUpRight size={13}/></button></>},
  {n:3,title:'Groq API key',description:'Task-specific model routing for writing, diagnosis, chat, and review.',fields:<><div className="setup-grid"><label>GROQ_API_KEY<input type="password" autoComplete="new-password" value={data.settings.groqKey||''} onChange={e=>onSetting('groqKey',e.target.value)} placeholder={data.settings.groqKeyConfigured==='true'?'Saved securely':'Paste your Groq key'}/></label><label>Writing model<input value={models.groq} onChange={e=>setModels({...models,groq:e.target.value})} placeholder="openai/gpt-oss-120b"/></label><label>Diagnosis model<input value={models.diagnosis} onChange={e=>setModels({...models,diagnosis:e.target.value})} placeholder="openai/gpt-oss-20b"/></label><label>Chat and tools model<input value={models.chat} onChange={e=>setModels({...models,chat:e.target.value})} placeholder="openai/gpt-oss-120b"/></label><label>Draft reviewer model<input value={models.reviewer} onChange={e=>setModels({...models,reviewer:e.target.value})} placeholder="openai/gpt-oss-20b"/></label></div></>},
  {n:4,title:'NVIDIA NIM API key',description:'Fallback provider. Leave its model blank to discover an available model from the provider.',fields:<><div className="setup-grid"><label>NVIDIA_API_KEY<input type="password" autoComplete="new-password" value={data.settings.nvidiaKey||''} onChange={e=>onSetting('nvidiaKey',e.target.value)} placeholder={data.settings.nvidiaKeyConfigured==='true'?'Saved securely':'Paste your NVIDIA key'}/></label><label>NVIDIA model<input value={models.nvidia} onChange={e=>setModels({...models,nvidia:e.target.value})} placeholder="Discover from provider"/></label><label>Hugging Face API key<input type="password" autoComplete="new-password" value={data.settings.huggingfaceKey||''} onChange={e=>onSetting('huggingfaceKey',e.target.value)} placeholder={data.settings.huggingfaceKeyConfigured==='true'?'Saved securely':'Optional fallback key'}/></label><label>Hugging Face model<input value={models.huggingface} onChange={e=>setModels({...models,huggingface:e.target.value})} placeholder="Discover from provider"/></label></div></>},
  {n:5,title:'Test each model provider',description:'Queue a live check for each configured provider and inspect its result in Activity.',fields:<div className="model-test-row"><button className="button-secondary" onClick={()=>onTest('groq')}>Test Groq <Zap size={13}/></button><button className="button-secondary" onClick={()=>onTest('nvidia')}>Test NVIDIA <Zap size={13}/></button><button className="button-secondary" onClick={()=>onTest('huggingface')}>Test Hugging Face <Zap size={13}/></button></div>},
  {n:6,title:'Send yourself a sample email',description:'Choose a connected account and the owner email. Real campaign sending also requires your valid postal address.',fields:<><label className="setup-field">Valid physical mailing address<input value={data.settings.senderAddress||''} onChange={e=>onSetting('senderAddress',e.target.value)} placeholder="Street, city, state ZIP" required/></label><div className="self-test-row"><input type="email" value={email} onChange={event=>setEmail(event.target.value)} placeholder="Your owner email"/><select aria-label="Sending Gmail account" value={accountId} onChange={event=>setAccountId(event.target.value)}><option value="">Choose Gmail account</option>{connectedAccounts.map((a:any)=><option key={a.id} value={a.id}>{a.email}</option>)}</select><button className="button-primary" onClick={onSelfSend} disabled={!email||!accountId}><Send size={14}/> Send an email to me</button></div></>},
  {n:7,title:'Operator notifications',description:'Alerts are sent only to your configured address. Quiet hours and the daily report use Luanda time.',fields:<><div className="setup-grid"><label>Notification email<input type="email" value={data.settings.notificationEmail||'lopesadilson948@gmail.com'} onChange={e=>onSetting('notificationEmail',e.target.value)}/></label><label>Notification sender account<select value={data.settings.notificationAccountId||''} onChange={e=>onSetting('notificationAccountId',e.target.value)}><option value="">Use Gmail account 1</option>{connectedAccounts.map((a:any)=><option key={a.id} value={a.id}>{a.email}</option>)}</select></label><label>Quiet hours start · Luanda<input type="time" value={data.settings.notificationQuietStart||'23:00'} onChange={e=>onSetting('notificationQuietStart',e.target.value)}/></label><label>Quiet hours end · Luanda<input type="time" value={data.settings.notificationQuietEnd||'07:00'} onChange={e=>onSetting('notificationQuietEnd',e.target.value)}/></label><label>Daily summary · Luanda<input type="time" value={data.settings.notificationSummaryAt||'21:00'} onChange={e=>onSetting('notificationSummaryAt',e.target.value)}/></label></div></>},
 ];
 return <div className="setup-layout"><section className="panel setup-panel"><div className="setup-intro"><span className="section-label">PHASE 4 · FINAL SETUP</span><h2>Connect your real accounts when you’re ready.</h2><p>The rest of the workspace works with synthetic examples. Secrets are encrypted on the private server and never returned to the browser.</p><div className="setup-progress"><i style={{width:`${flags.filter(Boolean).length/steps.length*100}%`}}/></div></div>{steps.map((step,index)=><section className="setup-step" key={step.n}><span className={`step-state ${flags[index]?'done':'pending'}`}>{flags[index]?<Check size={14}/>:<X size={14}/>}</span><div className="step-body"><div className="step-head"><h3>{step.title}</h3><span>{flags[index]?'COMPLETE':'NOT COMPLETE'}</span></div><p>{step.description}</p>{step.fields}</div></section>)}<div className="setup-footer"><button className="button-primary" onClick={onSave}><ShieldCheck size={14}/> Save settings securely</button><p>OAuth tokens and provider keys are encrypted at rest. Secrets never appear in API responses.</p><a className="button-secondary" href="/api/export">Export everything · CSV + workspace dump <ArrowRight size={13}/></a><a className="button-secondary" href="/install">Install on iPhone or Android <ArrowRight size={13}/></a></div></section><aside className="panel setup-side"><span className="section-label">PER ACCOUNT LIMITS</span><b>Up to 100 sends per day</b><p>25/day for days 1–3 · 50/day for days 4–7 · up to 100/day from day 8, subject to Gmail’s actual limits.</p><div className="ramp-line"><span/><span/><span/></div><span className="section-label">WORKSPACE SECURITY</span><div className="privacy-row"><ShieldCheck size={15}/> Supabase as source of truth</div><div className="privacy-row"><ShieldCheck size={15}/> Server-side encrypted secrets</div><div className="privacy-row"><ShieldCheck size={15}/> Synthetic leads can’t reach Gmail</div><a className="env-link" href="/.env.example" target="_blank">View environment variables <ExternalLink size={13}/></a></aside></div>;
}
function GoogleMark(){return <b className="google-mark">G</b>;}

function LeadDrawer({lead,onClose,onResearch,onDraft,onReply,onBrief,onStage,onSuppress}:{lead:Lead;onClose:()=>void;onResearch:()=>void;onDraft:()=>void;onReply:()=>void;onBrief:()=>void;onStage:(status:string)=>void;onSuppress:()=>void;onOpenTask:(id:number)=>void}){
 return <div className="overlay" onClick={onClose}><section className="lead-drawer" onClick={event=>event.stopPropagation()}><header><div><span className="section-label">PROSPECT PROFILE · #{lead.id}</span><span className="score-pill"><Zap size={12}/>{lead.score||0}</span></div><button className="close-button" aria-label="Close prospect" onClick={onClose}><X size={17}/></button></header><div className="drawer-person"><span>{lead.name.slice(0,1).toUpperCase()}</span><div><h2>{lead.name}</h2><p>{lead.niche} · {lead.city}</p></div></div><div className="drawer-status-row"><span className={`stage-pill stage-${lead.status.toLowerCase().replaceAll(' ','-')}`}><i/>{statusLabel(lead.status)}</span><select aria-label="Prospect stage" value={lead.status} onChange={event=>onStage(event.target.value)}>{stages.map(stage=><option key={stage} value={stage}>{statusLabel(stage)}</option>)}</select></div><div className="detail-grid"><div><small>EMAIL</small><b>{lead.email||'Not found yet'}</b></div><div><small>WEBSITE</small><b>{lead.website||statusLabel(lead.siteStatus||'No website')}</b></div><div><small>SOURCE</small><b>{sourceLabel(lead.source)}</b></div><div><small>LEAD SCORE</small><b>{lead.score||0}/100</b></div></div><section className="drawer-section"><div className="drawer-section-head"><h3>Research evidence</h3><button onClick={onResearch}><FileSearch size={13}/> Research website</button></div>{lead.evidence?.length?lead.evidence.map(item=><div className="evidence-card" key={item.id}><span><Globe2 size={13}/></span><div><b>{item.observation}</b><small>{item.sourceUrl||'CSV data'} · {dateTime(item.observedAt)}</small></div></div>):<p className="subtle-copy">No evidence yet. Research the website before preparing a message.</p>}</section>{lead.reply&&<section className="reply-preview"><span className="section-label">INCOMING REPLY</span><p>“{lead.reply}”</p><small>{lead.summary}</small></section>}{lead.subject&&<section className="draft-preview"><span className="section-label">LATEST EMAIL</span><b>{lead.subject}</b><p>{lead.body}</p><button className="button-secondary" onClick={onDraft}>Edit draft <ArrowRight size={13}/></button></section>}{lead.demoBrief&&<section className="draft-preview"><span className="section-label">DEMO BRIEF</span><pre>{lead.demoBrief}</pre></section>}<div className="drawer-actions"><button className="button-secondary" onClick={onBrief}><Sparkles size={14}/> Prepare demo brief</button>{lead.status==='A aprovar'&&<button className="button-primary" onClick={onDraft}>Review email <ArrowRight size={13}/></button>}{(lead.status==='Quente'||lead.hot>0)&&<button className="button-primary" onClick={onReply}><MessageCircle size={14}/> Draft a reply</button>}{lead.email&&<button className="button-danger-quiet" onClick={onSuppress}>Suppress address <ShieldCheck size={13}/></button>}</div></section></div>;
}

function DraftModal({draft,onChange,onClose,onSave,onApprove,onReplySend}:{draft:DraftState;onChange:(draft:DraftState)=>void;onClose:()=>void;onSave:()=>void;onApprove:()=>void;onReplySend:()=>void}){
 return <div className="overlay modal-overlay" onClick={onClose}><section className="draft-modal" onClick={event=>event.stopPropagation()}><header><div><span className="section-label">{draft.reply?'REPLY TO CONVERSATION':'REVIEW BEFORE SENDING'}</span><h2>{draft.lead.name}</h2><small>To: {draft.lead.email}</small></div><button className="close-button" aria-label="Close editor" onClick={onClose}><X size={17}/></button></header>{!draft.reply&&<label>Subject<input value={draft.subject} onChange={event=>onChange({...draft,subject:event.target.value})}/></label>}<label>{draft.reply?'Reply':'Message'}<textarea rows={8} value={draft.body} onChange={event=>onChange({...draft,body:event.target.value})}/></label>{!draft.reply&&<div className="evidence-hint"><ShieldCheck size={14}/> First-touch emails can’t include pricing or a proposal. Verify every factual claim against the evidence on the prospect profile.</div>}<div className="draft-preview-footer"><button className="button-secondary" onClick={onClose}>Cancel</button>{draft.reply?<button className="button-primary" onClick={onReplySend}><Send size={14}/> Approve and send reply</button>:<><button className="button-secondary" onClick={onSave}>Save edits</button><button className="button-primary" onClick={onApprove}><Check size={14}/> Approve and send</button></>}</div></section></div>;
}

function CampaignModal({preview,mode,setMode,accountId,setAccountId,onClose,onLaunch}:{preview:any;mode:'review'|'auto';setMode:(mode:'review'|'auto')=>void;accountId:string;setAccountId:(id:string)=>void;onClose:()=>void;onLaunch:()=>void}){
 const accounts=preview?.accounts||[];
 return <div className="overlay modal-overlay" onClick={onClose}><section className="campaign-modal" onClick={event=>event.stopPropagation()}><header><div><span className="section-label">CAMPAIGN REVIEW</span><h2>Confirm the audience and sending mode.</h2><p>Messages are researched, evidence-checked, and scheduled under each Gmail account’s limits.</p></div><button className="close-button" onClick={onClose}><X size={17}/></button></header><div className="campaign-count"><span><UsersRound size={18}/></span><div><b>{preview?.count||0} eligible prospects</b><small>{preview?.skipped||0} skipped · {preview?.examples||0} synthetic</small></div><div className="account-cap-badges">{accounts.length?`${accounts.length} connected Gmail account${accounts.length===1?'':'s'}`:'Example workspace'}</div></div>{accounts.length>0&&<label className="campaign-account-select">Sending account<select value={accountId} onChange={event=>setAccountId(event.target.value)}><option value="">Choose account</option>{accounts.map((account:any)=><option key={account.id} value={account.id}>{account.email} · {account.sent_today||0}/{account.daily_cap||100} today</option>)}</select></label>}<div className="mode-cards"><button className={mode==='review'?'selected':''} onClick={()=>setMode('review')}><span className="mode-radio"/><b>REVIEW</b><small>AI prepares each message. You approve before it sends.</small><Mail size={17}/></button><button className={mode==='auto'?'selected':''} onClick={()=>setMode('auto')}><span className="mode-radio"/><b>AUTO PILOT</b><small>Confirm this audience once; approved campaign messages and follow-ups run within account limits.</small><Zap size={17}/></button></div><div className="send-policy"><ShieldCheck size={15}/><span>Up to 100 per account/day after warm-up · 25 → 50 → 100 · US business hours · Gmail limits still apply.</span></div><div className="campaign-preview-list">{(preview?.eligible||[]).slice(0,5).map((lead:any)=><span key={lead.id}><i>{lead.name.slice(0,1)}</i>{lead.name}<small>{lead.email}</small></span>)}{preview?.eligible?.length>5&&<small>+ {preview.eligible.length-5} more prospects</small>}</div><footer><button className="button-secondary" onClick={onClose}>Back</button><button className="button-primary" onClick={onLaunch} disabled={accounts.length>1&&!accountId}>{mode==='auto'?'Confirm campaign and start Auto Pilot':'Prepare drafts for review'} <ArrowRight size={14}/></button></footer></section></div>;
}

function GoalModal({value,setValue,currency,setCurrency,onClose,onSave}:{value:string;setValue:(v:string)=>void;currency:string;setCurrency:(v:string)=>void;onClose:()=>void;onSave:()=>void}){return <div className="overlay modal-overlay" onClick={onClose}><section className="goal-modal" onClick={event=>event.stopPropagation()}><header><div><span className="section-label">REVENUE GOAL</span><h2>Set your target.</h2></div><button className="close-button" aria-label="Close goal editor" onClick={onClose}><X size={17}/></button></header><label>Amount<input type="number" min="1" value={value} onChange={event=>setValue(event.target.value)}/></label><label>Goal currency<select value={currency} onChange={event=>setCurrency(event.target.value)}><option value="USD">USD · US dollar</option><option value="EUR">EUR · Euro</option></select></label><p>Deals stay in EUR. USD goals use the ECB reference rate, cached for offline use.</p><footer><button className="button-secondary" onClick={onClose}>Cancel</button><button className="button-primary" onClick={onSave}>Save goal <ArrowRight size={14}/></button></footer></section></div>;}

function CommandPalette({query,setQuery,onClose,onRun}:{query:string;setQuery:(q:string)=>void;onClose:()=>void;onRun:(command:string)=>void}){
 const commands=[...menu.map(item=>({id:item.name,label:item.label,sub:item.phase,icon:item.icon})),{id:'campaign',label:'Prepare campaign',sub:'Create drafts or confirm Auto Pilot',icon:Sparkles},{id:'sync',label:'Sync Gmail',sub:'Check for new replies',icon:Inbox},{id:'chat',label:'Ask the assistant',sub:'Query your workspace',icon:MessageCircle}];
 const filtered=commands.filter(item=>`${item.label} ${item.sub}`.toLowerCase().includes(query.toLowerCase()));
 return <div className="overlay palette-overlay" onClick={onClose}><section className="command-palette" onClick={event=>event.stopPropagation()}><div className="palette-search"><Search size={18}/><input autoFocus placeholder="What do you want to do?" value={query} onChange={event=>setQuery(event.target.value)}/><kbd>ESC</kbd></div><div className="palette-commands">{filtered.map(item=>{const Icon=item.icon;return <button key={item.id} onClick={()=>onRun(item.id)}><span><Icon size={16}/></span><b>{item.label}</b><small>{item.sub}</small><ArrowRight size={14}/></button>;})}{!filtered.length&&<p>No matching actions.</p>}</div><footer><span><kbd>↑</kbd><kbd>↓</kbd> navigate</span><span><kbd>↵</kbd> open</span><span><kbd>⌘K</kbd> close</span></footer></section></div>;
}
